CustomField.formula:
IF(TEXT(Citizenship__c) == 'UNITED STATES',
			IF(TEXT(Proof_of_Citizenship__c) == 'Naturalization',20,null),
			IF(TEXT(Proof_of_work_permit_in_United_States__c) == 'Visa with stamped date of US entry',22,
						IF(TEXT(Proof_of_work_permit_in_United_States__c) == 'US Permanent Resident Card'
									|| TEXT(Proof_of_work_permit_in_United_States__c) == 'Permanent Resident Card Expired - Extension Granted',4,
									IF(TEXT(Proof_of_work_permit_in_United_States__c) == 'F-1 Student Visa',26,null)
								)
					) 
		)
